    private static string Root()=>Path.Combine(Path.GetTempPath(),"BrainstormingP10",Guid.NewGuid().ToString());
    internal static byte[] Wav(int frames=8000,bool silent=false){var wav=new byte[44+frames*2];"RIFF"u8.CopyTo(wav);BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(4),wav.Length-8);"WAVEfmt "u8.CopyTo(wav.AsSpan(8));BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(16),16);BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(20),1);BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(22),1);BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(24),16000);BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(28),32000);BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(32),2);BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(34),16);"data"u8.CopyTo(wav.AsSpan(36));BinaryPrimitives.WriteInt32LittleEndian(wav.AsSpan(40),frames*2);if(!silent)for(int i=0;i<frames;i++)BinaryPrimitives.WriteInt16LittleEndian(wav.AsSpan(44+i*2),(short)(Math.Sin(i*.1)*1000));return wav;}
    internal sealed class Speech(BrainstormingConversationTests.Provider conversation):IAiProvider,IAiBillingProvider,IAiRouter {
        public int Calls;public string Mode="complete";public TaskCompletionSource Started=new(TaskCreationOptions.RunContinuationsAsynchronously);public TaskCompletionSource Released=new(TaskCreationOptions.RunContinuationsAsynchronously);
        public string? TextOverride;public BrainstormingRecognitionQuality Quality;
        public string ProviderId=>"synthetic-speech";public AiProviderCapabilities Capabilities=>new(false,false,true);public bool RequiresEntitlement=>true;public bool IsBillable=>true;
        public AiProviderSelection Route(AiRequest r)=>r.Modalities.Contains(AiModality.Audio)?new(this,ProviderId,false,"synthetic"):conversation.Route(r);
        public async Task<AiResult> ExecuteAsync(AiRequest r,CancellationToken ct){Calls++;conversation.Request=r;Started.TrySetResult();if(Mode=="wait")await Released.Task.WaitAsync(ct);if(Mode=="disconnect")throw new HttpRequestException("Synthetic disconnect");return new(r.RequestId,[],new(100,20,TimeSpan.Zero),new(){{"text",TextOverride??(Mode=="poor"?"":(string)r.Inputs["language"]=="sv"?"Åsa väntade vid dörren.":"She waited at the door.")},{"recognitionQuality",Quality}});}
    }
