    private sealed class Microphone:IBrainstormingMicrophone {
        public int Starts;public Recording? Current;public TaskCompletionSource Started=new(TaskCreationOptions.RunContinuationsAsynchronously);
        public Task<BrainstormingCapability> AvailabilityAsync(CancellationToken ct=default)=>Task.FromResult(new BrainstormingCapability(BrainstormingCapabilityState.Available,"Synthetic microphone lifecycle only"));
        public Task<IBrainstormingRecording> StartAsync(CancellationToken ct=default){ct.ThrowIfCancellationRequested();Starts++;Current=new();Started.TrySetResult();return Task.FromResult<IBrainstormingRecording>(Current);}
        public Task CancelAsync()=>Current?.CancelAsync()??Task.CompletedTask;
        public sealed class Recording:IBrainstormingRecording {private readonly TaskCompletionSource<byte[]> source=new(TaskCreationOptions.RunContinuationsAsynchronously);public bool Released;public Task<byte[]> Audio=>source.Task;public Task StopAsync(){Released=true;source.TrySetResult(Wav());return Task.CompletedTask;}public Task CancelAsync(){Released=true;source.TrySetCanceled();return Task.CompletedTask;}public ValueTask DisposeAsync(){Released=true;source.TrySetCanceled();return ValueTask.CompletedTask;}}
