    private sealed class LostResponse(BrainstormingScope server,string mode,CancellationTokenSource cancellation):IBrainstormingSpeechTranscriber {
        public int Calls;private BrainstormingSpeechResult? result;
        public Task PrepareAsync(BrainstormingScope local,CancellationToken ct=default)=>Task.CompletedTask;
        public Task<BrainstormingSpeechResult> TranscribeAsync(BrainstormingScope local,Guid operation,string language,byte[] wav,CancellationToken ct=default){Calls++;result=new(1,server,operation,language,BrainstormingSpeechState.Completed,"Recognized final text.","Correct before sending",new(BrainstormingUsageState.Settled,"synthetic","synthetic",10,2));if(mode=="cancel")cancellation.Cancel();if(mode=="lost")throw new HttpRequestException("Synthetic response loss");return Task.FromResult(result);}
        public Task<BrainstormingSpeechResult?> InspectAsync(BrainstormingScope local,Guid operation,CancellationToken ct=default)=>Task.FromResult(result);
    }
    [Theory][InlineData("lost")][InlineData("cancel")][InlineData("full")]
    public async Task DurableJournalInspectsLostLateOrOverfullResultsWithoutReuploadOrDuplicateAppend(string mode) {
        await using var f=new BrainstormingConversationTests.Fixture();await f.Start(true);var server=(await new BrainstormingSessions(f.Db,"author",f.Data.Backend).ReadAsync(f.Data.Document,f.Send.Scope.SessionId,default))!;var local=server.Scope with {Space=BrainstormingIdentitySpace.Local};var root=Root();var files=new LocalBrainstormingStore(root);var composer=mode=="full"?new string('x',8000):"Typed message";await files.WriteAsync(new(1,1,BrainstormingPersistence.ReScope(server,local),composer,new(1,local,server.Scope,server.Revision,DateTimeOffset.UtcNow),null,null,[],[]),0,Guid.NewGuid());using var cancelled=new CancellationTokenSource();var remote=new LostResponse(server.Scope,mode,cancelled);var workflow=new BrainstormingDictationWorkflow(files,remote);
        if(mode=="lost")await Assert.ThrowsAsync<HttpRequestException>(()=>workflow.TranscribeAsync(local,"en",Wav()));else if(mode=="cancel")await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>workflow.TranscribeAsync(local,"en",Wav(),cancelled.Token));else await workflow.TranscribeAsync(local,"en",Wav());
        var cache=(await files.ReadAsync(local))!;Assert.Equal(composer,cache.Composer);Assert.Empty(cache.Session.Turns);Assert.Empty(cache.Session.Drafts);Assert.False(cache.Dictations!.Single().Adopted);Assert.DoesNotContain("wav",BrainstormingPersistence.Json(cache),StringComparison.OrdinalIgnoreCase);files=new(root);workflow=new(files,remote);
        if(mode=="full"){cache=cache with {Composer="Corrected shorter message"};await files.WriteAsync(cache,cache.CacheRevision,Guid.NewGuid());}var inspected=await workflow.InspectAsync(local);Assert.EndsWith("\nRecognized final text.",inspected.Composer);Assert.True(inspected.Dictations!.Single().Adopted);Assert.Equal(inspected.Composer,(await workflow.InspectAsync(local)).Composer);Assert.Equal(1,remote.Calls);
    }
    [Theory][InlineData("permission")][InlineData("quota")][InlineData("foreign")][InlineData("cancel")][InlineData("timeout")]
    public async Task AdmissionAndInterruptionCannotCreateTurnsOrApplicableText(string mode) {
        await using var f=new BrainstormingConversationTests.Fixture();await f.Start(true);var speech=new Speech(f.Provider){Mode=mode is "cancel" or "timeout"?"wait":"complete"};if(mode=="permission")f.Provider.Allowed=false;if(mode=="quota")f.Provider.QuotaAllowed=false;
        var service=new BrainstormingDictationService(f.Db,speech,f.Provider,f.Provider,f.Provider,Options.Create(new WriterAiOptions{Speech=new(){Model="gpt-4o-mini-transcribe",TimeoutSeconds=1}}),f.Stops,mode=="foreign"?"other":"author",f.Data.Backend);
        using var cancel=new CancellationTokenSource();var request=new BrainstormingSpeechRequest(1,f.Send.Scope,Guid.NewGuid(),"en",Wav());var before=(await f.Db.Pages.SingleAsync()).Content;
        if(mode is "cancel" or "timeout") {var pending=service.TranscribeAsync(request,cancel.Token);await speech.Started.Task.WaitAsync(TimeSpan.FromSeconds(10));if(mode=="cancel")cancel.Cancel();var outcome=await pending.WaitAsync(TimeSpan.FromSeconds(5));Assert.Equal(BrainstormingSpeechState.Unknown,outcome.State);Assert.Empty(outcome.Text);Assert.Equal(1,f.Provider.Charges);}
        else {if(mode=="foreign")await Assert.ThrowsAsync<BrainstormingAccessException>(()=>service.TranscribeAsync(request,default));else await Assert.ThrowsAsync<BrainstormingSpeechException>(()=>service.TranscribeAsync(request,default));Assert.Equal(0,speech.Calls);Assert.Equal(0,f.Provider.Charges);Assert.Empty(await f.Db.BrainstormingTranscriptions.ToArrayAsync());}
        Assert.Equal(before,(await f.Db.Pages.SingleAsync()).Content);Assert.Empty((await new BrainstormingSessions(f.Db,"author",f.Data.Backend).ReadAsync(f.Data.Document,f.Send.Scope.SessionId,default))!.Turns);
    }
    [Fact] public async Task AuthenticatedTransportRejectsUnsignedForeignMalformedAndLateIdentityResults() {
        await using var f=new BrainstormingConversationTests.Fixture();await f.Start(true);var speech=new Speech(f.Provider);using var host=await Host(f,true,speech);using var client=host.GetTestClient();client.BaseAddress=new("https://test.invalid/");var request=new BrainstormingSpeechRequest(1,f.Send.Scope,Guid.NewGuid(),"en",Wav());
        Assert.Equal(HttpStatusCode.Unauthorized,(await client.PostAsJsonAsync("api/brainstorming/dictation",request,BrainstormingValidation.Json)).StatusCode);client.DefaultRequestHeaders.Add("X-Test-Identity","other");Assert.Equal(HttpStatusCode.NotFound,(await client.PostAsJsonAsync("api/brainstorming/dictation",request,BrainstormingValidation.Json)).StatusCode);Assert.Equal(0,speech.Calls);
        bool current=true;using var delayed=new HttpClient(new Handler(r=>{current=false;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=JsonContent.Create(new BrainstormingSpeechResult(1,request.Scope,request.OperationId,"en",BrainstormingSpeechState.Completed,"Late private text","final",new(BrainstormingUsageState.Settled,"test","test",10,1)),options:BrainstormingValidation.Json)});}));
        var adapter=new BrainstormingSpeechHttp(delayed,_=>new(()=>{if(!current)throw new BrainstormingAccessException();}),(_,_)=>Task.FromResult(request.Scope));delayed.BaseAddress=new("https://test.invalid/");await Assert.ThrowsAsync<BrainstormingAccessException>(()=>adapter.TranscribeAsync(request.Scope,request.OperationId,"en",Wav()));
        using var malformed=new HttpClient(new Handler(_=>Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent("{broken")}))){BaseAddress=new("https://test.invalid/")};await Assert.ThrowsAsync<InvalidDataException>(()=>new BrainstormingSpeechHttp(malformed,_=>new(()=>{}),(_,_)=>Task.FromResult(request.Scope)).TranscribeAsync(request.Scope,request.OperationId,"en",Wav()));
    }
    [Fact] public async Task AuthorDictatedProposalUsesExactKeepApprovalAndGuardedUndo() {
