        var server=new BrainstormingSessions(f.Db,"author",f.Data.Backend);var session=(await server.ReadAsync(f.Data.Document,f.Send.Scope.SessionId,default))!;var draft=new BrainstormingDraft(1,Guid.NewGuid(),session.Scope,Guid.Empty,Guid.Empty,f.Context.Id,f.Target.Id,null,1,true,"Author dictation","Åsa väntade. Corrected.","Unapplied",[],DateTimeOffset.UtcNow,BrainstormingDraftContent.Html("Åsa väntade. Corrected."),Origin:BrainstormingDraftOrigin.AuthorDictated,DictationOperationId:operation);await server.WriteAsync(new(1,Guid.NewGuid(),session.Revision,session with {Revision=session.Revision+1,Drafts=[draft]}),default);
        var source=await new BrainstormingStorySourceReader(f.Db,"author").ReadAsync(f.Data.Document);var review=BrainstormingKeepContract.Review(session.Scope,draft,f.Target,BrainstormingKeepContract.Writing(source),null,null,"Author opening");var keep=new BrainstormingKeeps(f.Db,"author",f.Data.Backend);var original=(await f.Db.Pages.SingleAsync()).Content;Assert.Equal(BrainstormingApplicationState.Approved,(await keep.PrepareAsync(review)).State);Assert.Equal(original,(await f.Db.Pages.AsNoTracking().SingleAsync()).Content);Assert.Equal(BrainstormingApplicationState.Committed,(await keep.CommitAsync(review.Scope,review.OperationId)).State);Assert.Contains("Corrected.",(await f.Db.Pages.AsNoTracking().SingleAsync()).Content);Assert.Equal(BrainstormingApplicationState.Undone,(await keep.MoveAsync(review.Scope,review.OperationId,new(Guid.NewGuid(),1,false))).State);Assert.Equal(original,(await f.Db.Pages.AsNoTracking().SingleAsync()).Content);Assert.Empty((await server.ReadAsync(f.Data.Document,session.Scope.SessionId,default))!.Turns);Assert.Equal(1,speech.Calls);
    }
